steps.text:
/*
	VIOC_ai_tactics.sqf - parche ai_tactics de VIOC (2026-10-17). No es del autor de la mision.
	Lo carga init.sqf SOLO en el servidor (en la partida LAN el anfitrion es el servidor: la consola LOCAL EXEC llega aqui).

	Tacticas para la IA de los dos bandos (amiga y enemiga) y para las guarniciones de pueblo (tambien la guerrilla):
	1) CONTRAATAQUE: cuando Oeste o Este pierde un pueblo, a los 2-5 min lo contraataca con hasta 2 escuadras IA de tierra
	   cercanas (3 en la capital y en los pueblos con aerodromo), a menos de 4 km (6 km para capital y aerodromos) y con
	   camino por tierra (en linea recta no mas de 350 m de agua seguida: puentes y canales si, otra isla no). Capital y
	   aerodromos: siempre que haya escuadras libres; los demas pueblos: con una probabilidad segun su valor (maxSV, sitio
	   militar). Si el pueblo sigue perdido, reintenta cada 10 min durante 30 min (lobby VIOC_AI_CA_PERSIST).
	   Aviso al bando que contraataca: "[Contraataque] ...". Al bando enemigo nada (o un aviso vago con VIOC_AI_CA_INTEL = 1).
	2) PINZA (en los contraataques y en los ataques normales de 2-3 escuadras de un bando al mismo pueblo, a 0.7-2.2 km):
	   centro de la amenaza (enemigos dentro del radio del pueblo; como mucho a 300 m del centro), un punto de reunion por
	   escuadra a 400-600 m del objetivo y a +-60-90 grados del rumbo de llegada (con 3: izquierda, centro y derecha), en
	   tierra. La ida a la reunion es una orden MOVE de la propia mision (cti_order = CTI_ORDER_MOVE, cti_order_pos = el
	   punto): update_ai.fsm da el "move" y ai_transport (si esta) lleva a la infanteria hasta alli. Espera a que lleguen
	   todas (o 4 min desde la primera, o el plazo segun la distancia: 5-20 min) y asalto simultaneo: vioc_tac_busy = true
	   (gancho en update_ai.fsm: no reparte ordenes a ese grupo), puntos de ruta propios (MOVE a mitad de camino, SAD sobre
	   la amenaza, SAD y MOVE al centro del pueblo, CYCLE), modo ROJO / COMBATE y fuego de supresion (doSuppressiveFire de
	   2 hombres por escuadra a enemigos que el jefe conoce). Termina al tomar el pueblo, a los 12 min de asalto o si quedan
	   menos del 25 % de los hombres. Al terminar cada escuadra recupera su orden (las automaticas como TAKETOWNS o
	   TAKEHOLDTOWNS, para que la mision vuelva a elegir el pueblo) con cti_team_reload (sin mensaje de orden), y su modo
	   de combate, comportamiento y velocidad.
	3) PINZA DEFENSIVA (guarniciones de cualquier duenio; primero la capital y los aerodromos): si un jefe de la guarnicion
	   conoce (targets, knowsAbout > 1.5) a un grupo atacante a 150 m o mas del centro y dentro del radio del pueblo + 300 m,
	   hasta 2 grupos de patrulla de la guarnicion (no las dotaciones de estaticas; 3 hombres o mas) salen a dos puntos a los
	   lados del atacante (250 m en perpendicular) y luego convergen sobre el (SAD, ROJO, supresion). El resto sigue en el
	   pueblo; en la capital sale como mucho la mitad de los grupos (en los demas queda al menos uno). Dura 5 min como
	   maximo; 6 min de espera por pueblo. Gancho en town_patrol.fsm: la patrulla no da ordenes a un grupo con vioc_tac_busy.
	Nunca toca grupos con jugadores, el del comandante, aereos, operaciones especiales (vioc_specops), regresos a base de
	airfields (vioc_air_busy), alertas (vioc_af_scramble), tripulaciones de ai_transport ni grupos cuyo jefe reaparece.
	Con un jugador de comandante solo usa escuadras con ordenes automaticas (no las que el jugador mando a un pueblo o
	punto); si alguien cambia la orden de una escuadra durante la maniobra, la escuadra sale de la maniobra con esa orden.
	No crea unidades: usa los grupos que ya existen (el presupuesto de IA de perf_cleanup no cambia). Un bucle cada 20 s.
	Parametros de lobby: VIOC_AI_TACTICS, VIOC_AI_COUNTERATTACK, VIOC_AI_CA_PERSIST, VIOC_AI_PINCER, VIOC_AI_CA_INTEL.

	CONTRAATAQUE FORZADO (v2, 2026-10-17; VIOC_TAC_fnc_forceCA, pedidos con forced = true: la consola y la ofensiva de la
	mision B, mission_b_rules): busca escuadras hasta VIOC_TAC_CA_RANGE_FORCED m (9 km) y tambien acepta a las que estan por
	tomar otro pueblo (a menos de 700 m de el); el 3.er parametro fija cuantas escuadras (tambien en los reintentos); el plazo
	de reunion llega a VIOC_TAC_GATHER_FORCED s; esas maniobras no cuentan para el tope VIOC_TAC_MAX_MAN (VIOC_TAC_fnc_nMan),
	si para el reparto VIOC_TAC_MAX_SHARE. Los contraataques automaticos (perdida de un pueblo) no cambian.

	Consola (LOCAL EXEC en el anfitrion):
	  hint (call VIOC_TAC_fnc_info);               estado de maniobras, pedidos de contraataque y pinzas defensivas (portapapeles)
	  call VIOC_TAC_fnc_markers;                   marcadores locales en el mapa de lo que esta en marcha (otra vez: apagar)
	  hint ([] call VIOC_TAC_fnc_forceCA);         contraataque YA sobre el pueblo mas cercano a ti (el bando contrario al duenio)
	  hint ([call VIOC_TAC_fnc_nearTown, east] call VIOC_TAC_fnc_forceCA);   ... de un bando dado
	  hint ([call VIOC_TAC_fnc_nearTown, east, 2] call VIOC_TAC_fnc_forceCA);   ... con 2 escuadras (1-3)
	  hint ([] call VIOC_TAC_fnc_forceQRF);        pinza defensiva YA en el pueblo mas cercano (si su guarnicion ve atacantes)
	  call VIOC_TAC_fnc_stopAll;                   termina todo y devuelve las ordenes
	  VIOC_TAC_DEBUG = true;                       cada paso en systemChat del anfitrion
	  VIOC_TAC_INFO = [contraataques, recuperados, fallidos, pinzas, pinzas con exito, pinzas defensivas, defensivas con exito]
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_TAC_RUNNING") exitWith {};
VIOC_TAC_RUNNING = true;

//--- Ajustes
VIOC_TAC_PERIOD = 20;              // s por pasada del bucle
VIOC_TAC_CA_DELAY = [120, 300];    // s: el contraataque sale entre 2 y 5 min despues de perder el pueblo
VIOC_TAC_CA_RANGE = 4000;          // m: escuadras candidatas
VIOC_TAC_CA_RANGE_VIP = 6000;      // m: capital y aerodromos
VIOC_TAC_CA_RANGE_FORCED = 9000;   // m: contraataque forzado (forceCA: consola y ofensiva de la mision B)
VIOC_TAC_CA_TEAMS = 2;             // escuadras por contraataque (pueblo normal)
VIOC_TAC_CA_TEAMS_VIP = 3;         // capital y aerodromos
VIOC_TAC_HOLD_PENALTY = 1500;      // m de mas al elegir escuadras que defienden otro pueblo (HOLD)
VIOC_TAC_BIG_SV = 80;              // maxSV desde el que un pueblo cuenta como importante (opcion 1)
VIOC_TAC_MIN_UNITS = 3;            // hombres vivos minimos de una escuadra para una maniobra
VIOC_TAC_ASM_R = [400, 600];       // m del objetivo a los puntos de reunion
VIOC_TAC_ASM_A = [60, 90];         // grados a cada lado del rumbo de llegada
VIOC_TAC_ARRIVE = 120;             // m: llego a la reunion
VIOC_TAC_WAIT_REST = 240;          // s que se espera al resto desde la primera llegada
VIOC_TAC_GATHER = [300, 1200];     // s: plazo de reunion (segun la distancia, a VIOC_TAC_SPEED m/s + 2 min)
VIOC_TAC_GATHER_FORCED = 2700;     // s: plazo de reunion maximo de un contraataque forzado (las escuadras pueden estar a 9 km)
VIOC_TAC_SPEED = 2;
VIOC_TAC_ASSAULT_TIME = 720;       // s de asalto
VIOC_TAC_OBJ_CLAMP = 300;          // m: el objetivo del asalto queda a menos de esto del centro del pueblo
VIOC_TAC_WIPE = 0.25;              // fracaso si quedan menos de esta parte de los hombres del asalto
VIOC_TAC_PIN_R = [700, 2200];      // m del pueblo a los que tienen que estar las escuadras de un ataque normal
VIOC_TAC_PIN_COOLDOWN = 900;       // s entre pinzas del mismo bando sobre el mismo pueblo
VIOC_TAC_MAX_MAN = 2;              // maniobras a la vez por bando (+1 para capital y aerodromos)
VIOC_TAC_MAX_SHARE = 0.75;         // parte maxima de las escuadras de tierra de un bando en maniobras (al menos 2)
VIOC_TAC_WATER_GAP = 350;          // m de agua seguida en linea recta que todavia se acepta
VIOC_TAC_QRF_MAX = 4;              // pinzas defensivas a la vez en el mapa
VIOC_TAC_QRF_TOWNS = 4;            // pueblos normales revisados por pasada (la capital y los aerodromos siempre)
VIOC_TAC_QRF_OFFSET = 250;         // m en perpendicular al atacante
VIOC_TAC_QRF_MINR = 150;           // m: atacantes mas cerca del centro ya estan dentro (no hay flanqueo)
VIOC_TAC_QRF_EXTRA = 300;          // m: atacantes hasta el radio del pueblo + esto
VIOC_TAC_QRF_FLANK_TIME = 180;     // s maximos para llegar a los flancos
VIOC_TAC_QRF_TIME = 300;           // s maximos convergiendo
VIOC_TAC_QRF_COOLDOWN = 360;       // s de espera por pueblo
if (isNil "VIOC_TAC_DEBUG") then {VIOC_TAC_DEBUG = false};

//--- Estado (servidor)
VIOC_TAC_ON = 1;
VIOC_TAC_CA_MODE = 2;
VIOC_TAC_PERSIST = 1;
VIOC_TAC_PINCER = 2;
VIOC_TAC_INTEL = 0;
VIOC_TAC_MAN = [];                 // maniobras ofensivas (hashmaps)
VIOC_TAC_REQ = [];                 // pedidos de contraataque (hashmaps)
VIOC_TAC_QRF = [];                 // pinzas defensivas (hashmaps)
VIOC_TAC_AF = [];                  // pueblos con aerodromo
VIOC_TAC_INFO = [0, 0, 0, 0, 0, 0, 0];
VIOC_TAC_NEXTID = 1;
VIOC_TAC_READY = false;

//=====================================================================================================================
// Utilidades
//=====================================================================================================================
VIOC_TAC_fnc_log = {
	params ["_m"];
	diag_log format ["[VIOC ai_tactics] %1", _m];
	if (VIOC_TAC_DEBUG && {hasInterface}) then {systemChat format ["[TAC] %1", _m]};
};

//--- [bando, texto]: aviso a los jugadores de ese bando (como los demas avisos VIOC)
VIOC_TAC_fnc_say = {
	params ["_side", "_txt"];
	_txt remoteExec ["systemChat", _side];
	[format ["(%1) %2", _side, _txt]] call VIOC_TAC_fnc_log;
};

VIOC_TAC_fnc_stat = {
	params ["_i"];
	VIOC_TAC_INFO set [_i, (VIOC_TAC_INFO select _i) + 1];
};

//--- objeto o posicion -> [x, y, 0]
VIOC_TAC_fnc_p0 = {
	params ["_o"];
	private _p = if (_o isEqualType objNull) then {getPosATL _o} else {_o};
	[_p select 0, _p select 1, 0]
};

//--- [lista de posiciones] -> promedio [x, y, 0]
VIOC_TAC_fnc_avg = {
	params ["_pts"];
	private _sx = 0;
	private _sy = 0;
	{_sx = _sx + (_x select 0); _sy = _sy + (_x select 1)} forEach _pts;
	[_sx / ((count _pts) max 1), _sy / ((count _pts) max 1), 0]
};

//--- [punto, centro] -> el punto, acercado al centro si queda a mas de VIOC_TAC_OBJ_CLAMP
VIOC_TAC_fnc_clamp = {
	params ["_p", "_c"];
	if ((_p distance2D _c) > VIOC_TAC_OBJ_CLAMP) then {_p = _c getPos [VIOC_TAC_OBJ_CLAMP, _c getDir _p]};
	[_p select 0, _p select 1, 0]
};

//--- rumbo -> "el norte", "el noreste"...
VIOC_TAC_fnc_dirName = {
	params ["_b"];
	private _n = (round ((((_b % 360) + 360) % 360) / 45)) % 8;
	["el norte", "el noreste", "el este", "el sureste", "el sur", "el suroeste", "el oeste", "el noroeste"] select _n
};

VIOC_TAC_fnc_tname = {
	params ["_t"];
	_t getVariable ["cti_town_name", "?"]
};

//--- [bando] -> grupo del comandante (o grpNull)
VIOC_TAC_fnc_cmd = {
	params ["_side"];
	private _c = (_side) call CTI_CO_FNC_GetSideCommander;
	if (isNil "_c") then {_c = grpNull};
	if !(_c isEqualType grpNull) then {_c = grpNull};
	_c
};

//--- [unidad, radio] -> true si conoce un enemigo a menos de radio
VIOC_TAC_fnc_inCombat = {
	params ["_u", "_r"];
	private _e = _u findNearestEnemy _u;
	!isNull _e && {(_e distance _u) < _r}
};

//--- [desde, hasta] -> true si la linea recta no tiene mas de VIOC_TAC_WATER_GAP m de agua seguida (muestra cada 50 m)
VIOC_TAC_fnc_reachable = {
	params ["_a", "_b"];
	private _d = _a distance2D _b;
	private _n = ceil (_d / 50);
	private _step = _d / (_n max 1);
	private _run = 0;
	private _ok = true;
	for "_i" from 1 to (_n - 1) do {
		private _p = [(_a select 0) + ((_b select 0) - (_a select 0)) * _i / _n, (_a select 1) + ((_b select 1) - (_a select 1)) * _i / _n];
		_run = if (surfaceIsWater _p) then {_run + _step} else {0};
		if (_run > VIOC_TAC_WATER_GAP) exitWith {_ok = false};
	};
	_ok
};

//--- [centro, radios, rumbo] -> punto en tierra y dentro del mapa (rumbo +-45 grados) o []
VIOC_TAC_fnc_landPoint = {
	params ["_c", "_radii", "_b"];
	private _res = [];
	private _ws = worldSize;
	{
		private _off = _x;
		{
			private _p = _c getPos [_x, _b + _off];
			if (!(surfaceIsWater _p) && {(_p select 0) > 50} && {(_p select 1) > 50} && {(_p select 0) < (_ws - 50)} && {(_p select 1) < (_ws - 50)}) exitWith {_res = [_p select 0, _p select 1, 0]};
		} forEach _radii;
		if (count _res > 0) exitWith {};
	} forEach [0, 15, -15, 30, -30, 45, -45];
	_res
};

//--- [posiciones de los jefes, puntos] -> permutacion (indices de puntos) con menos recorrido total (hasta 3)
VIOC_TAC_fnc_bestPerm = {
	params ["_ls", "_pts"];
	private _n = ((count _ls) min 3) max 1;
	private _perms = [[[0]], [[0, 1], [1, 0]], [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]]] select (_n - 1);
	private _best = _perms select 0;
	private _bd = 1e12;
	{
		private _pm = _x;
		private _s = 0;
		{
			private _p = _pts select (_pm select _forEachIndex);
			if (count _p > 1) then {_s = _s + (_x distance2D _p)};
		} forEach (_ls select [0, _n]);
		if (_s < _bd) then {_bd = _s; _best = _pm};
	} forEach _perms;
	_best
};

//--- [grupo]: borra todos sus puntos de ruta
VIOC_TAC_fnc_clearWp = {
	params ["_g"];
	for "_i" from ((count (waypoints _g)) - 1) to 0 step -1 do {deleteWaypoint [_g, _i]};
};

//--- [grupo]: los que terminaron el fuego de supresion vuelven a la formacion
VIOC_TAC_fnc_refollow = {
	params ["_g"];
	private _l = leader _g;
	{
		private _t = _x getVariable ["vioc_tac_supT", -1];
		if (_t > 0 && {(time - _t) > 25} && {!((currentCommand _x) isEqualTo "Suppress")}) then {
			_x setVariable ["vioc_tac_supT", nil];
			if (alive _x && {!(_x isEqualTo _l)}) then {_x doFollow _l};
		};
	} forEach (units _g);
};

//--- [grupo, centro, radio] -> cuantos hombres del grupo abren fuego de supresion (2 como mucho) sobre enemigos que el
//--- jefe conoce a menos de 350 m del centro
VIOC_TAC_fnc_suppress = {
	params ["_g", "_c", "_r"];
	private _l = leader _g;
	if (isNull _l || {!alive _l}) exitWith {0};
	private _ts = (_l targets [true, _r]) select {alive _x && {(_l knowsAbout _x) > 1.5} && {(_x distance2D _c) < 350} && {!(_x isKindOf "Air")}};
	if (count _ts == 0) exitWith {0};
	private _sh = (units _g) select {alive _x && {!(_x isEqualTo _l)} && {isNull objectParent _x} && {local _x} && {!isPlayer _x}
		&& {!((currentCommand _x) isEqualTo "Suppress")} && {!((primaryWeapon _x) isEqualTo "")}};
	private _n = 0;
	while {_n < 2 && {count _sh > 0}} do {
		private _u = selectRandom _sh;
		_sh = _sh - [_u];
		private _tg = selectRandom _ts;
		if (((_u distance _tg) > 60) && {!(terrainIntersectASL [eyePos _u, (getPosASL _tg) vectorAdd [0, 0, 1]])}) then {
			_u doSuppressiveFire _tg;
			_u setVariable ["vioc_tac_supT", time];
			_n = _n + 1;
		};
	};
	_n
};

//--- [pueblo] -> [vip (capital o aerodromo), importante, peso 0-1, etiqueta]
VIOC_TAC_fnc_townInfo = {
	params ["_t"];
	private _cap = _t getVariable ["vioc_capital", false];
	private _af = _t in VIOC_TAC_AF;
	private _site = (_t getVariable ["vioc_site_mult", 1]) > 1;
	private _sv = _t getVariable ["cti_town_maxSV", 30];
	if !(_sv isEqualType 0) then {_sv = 30};
	private _vip = _cap || {_af};
	private _imp = _vip || {_site} || {_sv >= VIOC_TAC_BIG_SV};
	private _w = if (_vip) then {1} else {(0.3 + 0.55 * ((_sv min 120) / 120) + ([0, 0.15] select _site)) min 1};
	private _lab = if (_cap) then {"la capital "} else {if (_af) then {"el aerodromo de "} else {""}};
	[_vip, _imp, _w, _lab]
};

//--- [pueblo, bando] -> centro de los enemigos (de ese bando) dentro del radio del pueblo, acercado al centro; o el centro
VIOC_TAC_fnc_hostileCenter = {
	params ["_town", "_side"];
	private _tp = [_town] call VIOC_TAC_fnc_p0;
	private _hs = [west, east, resistance] - [_side];
	private _pts = [];
	{
		if (alive _x && {(side _x) in _hs}) then {_pts pushBack (getPosATL _x)};
	} forEach (_tp nearEntities [["Man", "Car", "Tank", "StaticWeapon"], _town getVariable ["cti_town_range", 550]]);
	private _c = if (count _pts > 0) then {[_pts] call VIOC_TAC_fnc_avg} else {_tp};
	[_c, _tp] call VIOC_TAC_fnc_clamp
};

//--- [jefes, centro, radio] -> posiciones (estimadas) de los enemigos que esos jefes conocen cerca del centro
VIOC_TAC_fnc_known = {
	params ["_leaders", "_c", "_r"];
	private _pts = [];
	{
		private _l = _x;
		if (!isNull _l && {alive _l}) then {
			{
				if (alive _x && {(_l knowsAbout _x) > 1.5} && {!(_x isKindOf "Air")}) then {_pts pushBack ((_l targetKnowledge _x) select 6)};
			} forEach (_l targets [true, _r, [], 180, _c]);
		};
	} forEach _leaders;
	_pts
};

//--- pueblos con aerodromo: para cada aeropuerto de CfgWorlds (principal y SecondaryAirports) el pueblo mas cercano a
//--- menos de 1500 m de su punto ILS (la regla de airfields / towns_capital), mas los de towns_capital si existen
VIOC_TAC_fnc_airfieldTowns = {
	private _w = configFile >> "CfgWorlds" >> worldName;
	private _cfgs = [_w];
	if (isClass (_w >> "SecondaryAirports")) then {_cfgs append ("true" configClasses (_w >> "SecondaryAirports"))};
	private _res = [];
	{
		private _p = getArray (_x >> "ilsPosition");
		if (count _p >= 2 && {!(((_p select 0) == 0) && {(_p select 1) == 0})}) then {
			private _pt = [_p select 0, _p select 1, 0];
			private _best = objNull;
			private _bd = 1500;
			{
				private _d = _x distance2D _pt;
				if (_d < _bd) then {_bd = _d; _best = _x};
			} forEach CTI_Towns;
			if (!isNull _best) then {_res pushBackUnique _best};
		};
	} forEach _cfgs;
	{_res pushBackUnique _x} forEach ((missionNamespace getVariable ["VIOC_TC_AF_TOWNS", []]) select {!isNull _x});
	_res
};

VIOC_TAC_fnc_nearTown = {
	private _c = if (hasInterface && {!isNull player}) then {getPosATL player} else {[0, 0, 0]};
	private _best = objNull;
	private _bd = 1e9;
	{
		private _d = _x distance2D _c;
		if (_d < _bd) then {_bd = _d; _best = _x};
	} forEach CTI_Towns;
	_best
};

//=====================================================================================================================
// Escuadras
//=====================================================================================================================
//--- [grupo, bando, comandante, comandante humano] -> true si la escuadra puede entrar en una maniobra
VIOC_TAC_fnc_teamOk = {
	params ["_g", "_side", "_cmd", "_human"];
	if (isNull _g || {_g isEqualTo _cmd}) exitWith {false};
	private _l = leader _g;
	if (isNull _l || {!alive _l} || {isPlayer _l} || {!local _l}) exitWith {false};
	if (((units _g) findIf {isPlayer _x}) >= 0) exitWith {false};
	if !(_g getVariable ["cti_aifsm_handled", false]) exitWith {false};
	if (!isNil {_g getVariable "vioc_tac_man"} || {_g getVariable ["vioc_tac_busy", false]}) exitWith {false};
	if ((_g getVariable ["vioc_air_busy", false]) || {_g getVariable ["vioc_af_scramble", false]} || {_g getVariable ["vioc_specops", false]} || {!isNil {_g getVariable "vioc_at_owner"}}) exitWith {false};
	if ((_g getVariable ["cti_nextrespawn", -1]) > time) exitWith {false};
	if ((_g getVariable ["cti_role", ""]) in (missionNamespace getVariable [format ["CTI_SQUADS_%1_KIND_AIR", _side], []])) exitWith {false};
	private _v = objectParent _l;
	if (!isNull _v && {(_v isKindOf "Air") || {_v isKindOf "Ship"}}) exitWith {false};
	if (({alive _x} count (units _g)) < VIOC_TAC_MIN_UNITS) exitWith {false};
	(_g getVariable ["cti_order", -1]) in ([VIOC_TAC_ORDERS_AI, VIOC_TAC_ORDERS_AUTO] select _human)
};

//--- [bando, comandante] -> cuantas escuadras mas pueden entrar en maniobras
VIOC_TAC_fnc_sideRoom = {
	params ["_side", "_cmd"];
	private _air = missionNamespace getVariable [format ["CTI_SQUADS_%1_KIND_AIR", _side], []];
	private _all = ((_side) call CTI_CO_FNC_GetSideGroups) select {!(_x isEqualTo _cmd) && {!isPlayer (leader _x)} && {!((_x getVariable ["cti_role", ""]) in _air)}};
	private _in = {!isNil {_x getVariable "vioc_tac_man"}} count _all;
	((2 max (ceil (VIOC_TAC_MAX_SHARE * (count _all)))) - _in) max 0
};

//--- [bando] -> maniobras de ese bando que cuentan para el tope VIOC_TAC_MAX_MAN (v2: las de un contraataque forzado no
//--- cuentan, para que la ofensiva de la mision B no bloquee los contraataques y pinzas normales hasta ~57 min)
VIOC_TAC_fnc_nMan = {
	params ["_side"];
	{((_x get "side") isEqualTo _side) && {!(((_x get "req") isEqualType createHashMap) && {(_x get "req") getOrDefault ["forced", false]})}} count VIOC_TAC_MAN
};

//--- [bando, pueblo, cuantas, alcance, forzado] -> escuadras para un contraataque (las mas cercanas); forzado: tambien las que
//--- van a tomar otro pueblo
VIOC_TAC_fnc_pickTeams = {
	params ["_side", "_town", "_n", "_range", ["_forced", false]];
	private _cmd = [_side] call VIOC_TAC_fnc_cmd;
	private _human = !isNull _cmd && {isPlayer (leader _cmd)};
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _tp = [_town] call VIOC_TAC_fnc_p0;
	_n = _n min ([_side, _cmd] call VIOC_TAC_fnc_sideRoom);
	if (_n < 1) exitWith {[]};
	private _gs = (_side) call CTI_CO_FNC_GetSideGroups;
	private _keys = [];
	{
		private _g = _x;
		if ([_g, _side, _cmd, _human] call VIOC_TAC_fnc_teamOk) then {
			private _l = leader _g;
			private _lp = getPosATL (vehicle _l);
			private _d = _lp distance2D _tp;
			if (_d < _range && {!([_l, 300] call VIOC_TAC_fnc_inCombat)}) then {
				private _o = _g getVariable ["cti_order", -1];
				private _p = _g getVariable ["cti_order_pos", objNull];
				//--- no se saca a una escuadra que esta por tomar otro pueblo (a menos de 700 m de el), salvo en un pedido forzado
				private _near = !_forced && {_o in VIOC_TAC_ORDERS_TAKE} && {_p isEqualType objNull} && {!isNull _p} && {!(_p isEqualTo _town)}
					&& {(_p getVariable ["cti_town_sideID", -1]) != _sid} && {(_lp distance2D _p) < 700};
				if (!_near && {[_lp, _tp] call VIOC_TAC_fnc_reachable}) then {
					_keys pushBack [_d + ([0, VIOC_TAC_HOLD_PENALTY] select (_o in [CTI_ORDER_HOLDTOWNSBASES, CTI_ORDER_HOLDTOWNSBASE])), _forEachIndex];
				};
			};
		};
	} forEach _gs;
	_keys sort true;
	(_keys select [0, _n]) apply {_gs select (_x select 1)}
};

//--- [grupo, orden, posicion]: orden de la mision, de una vez (sin que la FSM vea un estado a medias); semilla nueva para
//--- cortar el hilo de la orden anterior y cti_team_reload para que no se mande el mensaje de "nueva orden"
VIOC_TAC_fnc_setOrder = {
	params ["_g", "_order", "_pos"];
	isNil {
		_g setVariable ["cti_order_seed", time + random 100000];
		_g setVariable ["cti_team_reload", true];
		_g setVariable ["cti_order_pos", _pos, true];
		_g setVariable ["cti_order", _order, true];
	};
};

//--- [escuadra (hashmap), devolver la orden]: la escuadra sale de la maniobra
VIOC_TAC_fnc_release = {
	params ["_e", "_restore"];
	private _g = _e get "g";
	if (isNull _g) exitWith {};
	private _mine = ((_g getVariable ["cti_order", -1]) isEqualTo CTI_ORDER_MOVE) && {(_g getVariable ["cti_order_pos", []]) isEqualTo (_e get "my")};
	private _o = _e get "order";
	private _p = _e get "pos";
	if (_o in [CTI_ORDER_TAKETOWNS, CTI_ORDER_TAKETOWN_AUTO]) then {_o = CTI_ORDER_TAKETOWNS; _p = [0, 0]};
	if (_o in [CTI_ORDER_TAKEHOLDTOWNS, CTI_ORDER_TAKEHOLDTOWN_AUTO]) then {_o = CTI_ORDER_TAKEHOLDTOWNS; _p = [0, 0]};
	if ((_o == CTI_ORDER_HOLDTOWNSBASE) && {_p isEqualType objNull} && {isNull _p}) then {_o = CTI_ORDER_HOLDTOWNSBASES; _p = [0, 0]};
	private _wasBusy = _g getVariable ["vioc_tac_busy", false];
	//--- primero los puntos de ruta propios y los modos (mientras la FSM todavia no da ordenes), despues la orden
	if (local _g) then {
		if (_wasBusy) then {[_g] call VIOC_TAC_fnc_clearWp};
		_g setCombatMode (_e get "cm");
		_g setBehaviour (_e get "beh");
		_g setSpeedMode (_e get "spd");
		private _l = leader _g;
		{
			_x setVariable ["vioc_tac_supT", nil];
			if (alive _x && {!isPlayer _x} && {!(_x isEqualTo _l)}) then {_x doFollow _l};
		} forEach (units _g);
	};
	isNil {
		if (_restore && {_mine}) then {
			_g setVariable ["cti_team_reload", true];
			_g setVariable ["cti_order_pos", _p, true];
			_g setVariable ["cti_order", _o, true];
		} else {
			if (_wasBusy) then {_g setVariable ["cti_team_reload", true]}; //--- la orden que haya (la de otro) se vuelve a dar
		};
		_g setVariable ["vioc_tac_busy", nil];
		_g setVariable ["vioc_tac_man", nil];
	};
};

//=====================================================================================================================
// Maniobras ofensivas (contraataque y pinza)
//=====================================================================================================================
//--- [tipo ("ca" o "pin"), bando, pueblo, escuadras, pedido (hashmap)] -> id
VIOC_TAC_fnc_launch = {
	params ["_kind", "_side", "_town", "_teams", "_req"];
	private _id = VIOC_TAC_NEXTID;
	VIOC_TAC_NEXTID = VIOC_TAC_NEXTID + 1;
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _obj = [_town, _side] call VIOC_TAC_fnc_hostileCenter;
	private _n = count _teams;
	private _pin = (VIOC_TAC_PINCER > 0) && {_n > 1};
	private _ls = _teams apply {getPosATL (vehicle (leader _x))};
	private _b = _obj getDir ([_ls] call VIOC_TAC_fnc_avg);
	private _r = (VIOC_TAC_ASM_R select 0) + random ((VIOC_TAC_ASM_R select 1) - (VIOC_TAC_ASM_R select 0));
	private _a = (VIOC_TAC_ASM_A select 0) + random ((VIOC_TAC_ASM_A select 1) - (VIOC_TAC_ASM_A select 0));
	private _angs = if (_pin) then {[[_b - _a, _b + _a], [_b - _a, _b, _b + _a]] select (_n > 2)} else {_ls apply {_obj getDir _x}};
	private _pts = _angs apply {[_obj, [_r, _r - 100, _r + 100], _x] call VIOC_TAC_fnc_landPoint};
	private _perm = if (_pin) then {[_ls, _pts] call VIOC_TAC_fnc_bestPerm} else {[0, 1, 2] select [0, _n]};
	private _tl = [];
	private _dirs = [];
	private _far = 0;
	{
		private _g = _x;
		private _lp = _ls select _forEachIndex;
		private _p = _pts select (_perm select _forEachIndex);
		//--- sin punto en tierra o sin camino por tierra hasta el: el punto en el rumbo propio de la escuadra
		if (count _p < 2 || {!([_lp, _p] call VIOC_TAC_fnc_reachable)}) then {_p = [_obj, [_r, _r - 100, _r + 100], _obj getDir _lp] call VIOC_TAC_fnc_landPoint};
		if (count _p < 2) then {_p = [_lp select 0, _lp select 1, 0]};
		_far = _far max (_lp distance2D _p);
		_dirs pushBackUnique ([_obj getDir _p] call VIOC_TAC_fnc_dirName);
		private _e = createHashMapFromArray [["g", _g], ["asm", _p], ["my", _p], ["arr", false],
			["order", _g getVariable ["cti_order", CTI_ORDER_TAKETOWNS]], ["pos", _g getVariable ["cti_order_pos", [0, 0]]],
			["cm", combatMode _g], ["beh", behaviour (leader _g)], ["spd", speedMode _g]];
		_g setVariable ["vioc_tac_man", _id];
		[_g, CTI_ORDER_MOVE, _p] call VIOC_TAC_fnc_setOrder;
		_g setCombatMode "YELLOW";
		_tl pushBack _e;
	} forEach _teams;
	private _gmax = (((_far / VIOC_TAC_SPEED) + 120) max (VIOC_TAC_GATHER select 0)) min (VIOC_TAC_GATHER select 1);
	if ((_req isEqualType createHashMap) && {_req getOrDefault ["forced", false]}) then {
		_gmax = (((_far / VIOC_TAC_SPEED) + 120) max (VIOC_TAC_GATHER select 0)) min VIOC_TAC_GATHER_FORCED; //--- forzado: escuadras hasta a 9 km
	};
	private _m = createHashMapFromArray [["id", _id], ["kind", _kind], ["side", _side], ["sid", _sid], ["town", _town],
		["obj", _obj], ["phase", "gather"], ["t0", time], ["tp", time], ["tFirst", -1], ["gmax", _gmax], ["teams", _tl],
		["n0", 0], ["req", _req], ["pin", _pin], ["done", false]];
	VIOC_TAC_MAN pushBack _m;
	private _info = [_town] call VIOC_TAC_fnc_townInfo;
	private _tn = (_info select 3) + ([_town] call VIOC_TAC_fnc_tname);
	private _where = _dirs joinString " y ";
	private _esc = if (_n == 1) then {"1 escuadra"} else {format ["%1 escuadras", _n]};
	if (_kind == "ca") then {
		[0] call VIOC_TAC_fnc_stat;
		[_side, format ["[Contraataque] %1 %2 %3%4: reunion por %5 (a ~%6 m) y asalto %7.", _esc, if (_n == 1) then {"contraataca"} else {"contraatacan"}, _tn,
			if (_pin) then {" en pinza"} else {""}, _where, round _r, if (_n > 1) then {"simultaneo"} else {"sobre el pueblo"}]] call VIOC_TAC_fnc_say;
		if (VIOC_TAC_INTEL > 0) then {
			private _owner = _town getVariable ["cti_town_sideID", -1];
			if (_owner in [CTI_WEST_ID, CTI_EAST_ID] && {_owner != _sid}) then {
				[(_owner) call CTI_CO_FNC_GetSideFromID, format ["[Inteligencia] Se detecta movimiento enemigo hacia %1: posible contraataque.", [_town] call VIOC_TAC_fnc_tname]] call VIOC_TAC_fnc_say;
			};
		};
	} else {
		[3] call VIOC_TAC_fnc_stat;
		[_side, format ["[Tacticas] Ataque en pinza sobre %1: %2 se reunen por %3 (a ~%4 m) y asaltan a la vez.", _tn, _esc, _where, round _r]] call VIOC_TAC_fnc_say;
	};
	[format ["maniobra %1 (%2) de %3 sobre %4: %5 escuadras %6, objetivo %7, reunion en %8 (plazo %9 s)", _id, _kind, _side,
		[_town] call VIOC_TAC_fnc_tname, _n, _teams apply {groupId _x}, _obj, _tl apply {_x get "asm"}, round _gmax]] call VIOC_TAC_fnc_log;
	_id
};

//--- [maniobra, escuadra] -> "" si sigue, o por que sale
VIOC_TAC_fnc_teamWhy = {
	params ["_m", "_e"];
	private _g = _e get "g";
	if (isNull _g) exitWith {"grupo borrado"};
	if (({alive _x} count (units _g)) < 2) exitWith {"diezmada"};
	private _l = leader _g;
	if (isPlayer _l || {((units _g) findIf {isPlayer _x}) >= 0}) exitWith {"jugador"};
	if ((_g getVariable ["cti_nextrespawn", -1]) > time) exitWith {"el jefe reaparece"};
	if (!((_g getVariable ["cti_order", -1]) isEqualTo CTI_ORDER_MOVE) || {!((_g getVariable ["cti_order_pos", []]) isEqualTo (_e get "my"))}) exitWith {"orden"};
	if (((_m get "phase") == "assault") && {alive _l} && {((vehicle _l) distance2D (_m get "obj")) > 2500}) exitWith {"lejos"};
	""
};

//--- [grupo, objetivo, centro del pueblo]: puntos de ruta del asalto
VIOC_TAC_fnc_assaultWp = {
	params ["_g", "_obj", "_tp"];
	[_g] call VIOC_TAC_fnc_clearWp;
	_g setCombatMode "RED";
	_g setBehaviour "AWARE";
	_g setSpeedMode "NORMAL";
	private _lp = getPosATL (vehicle (leader _g));
	private _first = [];
	private _dl = _lp distance2D _obj;
	if (_dl > 350) then {
		private _mid = _obj getPos [(_dl / 2) min 300, _obj getDir _lp];
		if !(surfaceIsWater _mid) then {
			_first = _g addWaypoint [[_mid select 0, _mid select 1, 0], 20];
			_first setWaypointType "MOVE";
			_first setWaypointBehaviour "AWARE";
			_first setWaypointCombatMode "RED";
			_first setWaypointSpeed "NORMAL";
			_first setWaypointFormation "WEDGE";
			_first setWaypointCompletionRadius 50;
		};
	};
	private _w1 = _g addWaypoint [_obj, 30];
	_w1 setWaypointType "SAD";
	_w1 setWaypointBehaviour "COMBAT";
	_w1 setWaypointCombatMode "RED";
	_w1 setWaypointSpeed "NORMAL";
	_w1 setWaypointCompletionRadius 60;
	if (count _first == 0) then {_first = _w1};
	if ((_obj distance2D _tp) > 80) then {
		private _w2 = _g addWaypoint [_tp, 40];
		_w2 setWaypointType "SAD";
		_w2 setWaypointCompletionRadius 60;
	};
	private _w3 = _g addWaypoint [_tp, 20];
	_w3 setWaypointType "MOVE";
	_w3 setWaypointCompletionRadius 20;
	private _wc = _g addWaypoint [_tp, 50];
	_wc setWaypointType "CYCLE";
	_g setCurrentWaypoint _first;
};

//--- [maniobra]: asalto simultaneo
VIOC_TAC_fnc_assault = {
	params ["_m"];
	private _town = _m get "town";
	private _side = _m get "side";
	private _tp = [_town] call VIOC_TAC_fnc_p0;
	private _leaders = (_m get "teams") apply {leader (_x get "g")};
	private _pts = [_leaders, _tp, (_town getVariable ["cti_town_range", 550]) + 250] call VIOC_TAC_fnc_known;
	private _obj = if (count _pts > 0) then {[[_pts] call VIOC_TAC_fnc_avg, _tp] call VIOC_TAC_fnc_clamp} else {[_town, _side] call VIOC_TAC_fnc_hostileCenter};
	_m set ["obj", _obj];
	_m set ["phase", "assault"];
	_m set ["tp", time];
	private _n0 = 0;
	{
		private _e = _x;
		private _g = _e get "g";
		isNil {
			_g setVariable ["vioc_tac_busy", true];
			_g setVariable ["cti_order_pos", _obj, true];
		};
		_e set ["my", _obj];
		if (local _g) then {
			[_g, _obj, _tp] call VIOC_TAC_fnc_assaultWp;
			[_g, _obj, 700] call VIOC_TAC_fnc_suppress;
		};
		_e set ["n", {alive _x} count (units _g)];
		_n0 = _n0 + (_e get "n");
	} forEach (_m get "teams");
	_m set ["n0", _n0];
	private _tn = [_town] call VIOC_TAC_fnc_tname;
	private _nt = count (_m get "teams");
	[_side, format ["%1 Asalto %2sobre %3 (%4).", ["[Tacticas]", "[Contraataque]"] select ((_m get "kind") == "ca"),
		if (_nt > 1) then {"simultaneo "} else {""}, _tn, if (_nt == 1) then {"1 escuadra"} else {format ["%1 escuadras", _nt]}]] call VIOC_TAC_fnc_say;
	[format ["maniobra %1: asalto sobre %2 con %3 hombres (objetivo a %4 m del centro, %5 enemigos conocidos)", _m get "id", _tn, _n0, round (_obj distance2D _tp), count _pts]] call VIOC_TAC_fnc_log;
};

//--- [maniobra, motivo]
VIOC_TAC_fnc_end = {
	params ["_m", "_why"];
	if (_m get "done") exitWith {};
	_m set ["done", true];
	{[_x, true] call VIOC_TAC_fnc_release} forEach (_m get "teams");
	private _town = _m get "town";
	private _side = _m get "side";
	private _ok = (_town getVariable ["cti_town_sideID", -1]) == (_m get "sid");
	private _tn = [_town] call VIOC_TAC_fnc_tname;
	if ((_m get "kind") == "ca") then {
		private _r = _m get "req";
		if (_ok) then {
			[1] call VIOC_TAC_fnc_stat;
			[_side, format ["[Contraataque] %1 recuperado.", _tn]] call VIOC_TAC_fnc_say;
			_r set ["done", true];
		} else {
			[2] call VIOC_TAC_fnc_stat;
			private _next = (_r get "next") max (time + 120);
			_r set ["next", _next];
			_r set ["active", -1];
			private _more = if (_next < (_r get "end")) then {format ["nuevo intento en ~%1 min", ceil ((_next - time) / 60)]} else {"sin mas intentos"};
			[_side, format ["[Contraataque] El contraataque sobre %1 termino sin recuperarlo (%2); %3.", _tn, _why, _more]] call VIOC_TAC_fnc_say;
		};
	} else {
		if (_ok) then {
			[4] call VIOC_TAC_fnc_stat;
			[_side, format ["[Tacticas] %1 tomado tras el ataque en pinza.", _tn]] call VIOC_TAC_fnc_say;
		} else {
			[_side, format ["[Tacticas] El ataque en pinza sobre %1 termino (%2); las escuadras siguen con sus ordenes.", _tn, _why]] call VIOC_TAC_fnc_say;
		};
	};
	[format ["maniobra %1 terminada: %2 (pueblo %3 de %4: %5)", _m get "id", _why, _tn, _side, _ok]] call VIOC_TAC_fnc_log;
	VIOC_TAC_MAN = VIOC_TAC_MAN select {!(_x get "done")};
};

//--- [maniobra]: una pasada
VIOC_TAC_fnc_manTick = {
	params ["_m"];
	if (_m get "done") exitWith {};
	private _town = _m get "town";
	if ((_town getVariable ["cti_town_sideID", -1]) == (_m get "sid")) exitWith {[_m, "pueblo tomado"] call VIOC_TAC_fnc_end};
	//--- escuadras que salen
	{
		private _e = _x;
		private _why = [_m, _e] call VIOC_TAC_fnc_teamWhy;
		if (_why != "") then {
			[_e, _why != "orden"] call VIOC_TAC_fnc_release;
			_e set ["out", true];
			_m set ["n0", ((_m get "n0") - (_e getOrDefault ["n", 0])) max 0]; //--- el resto del asalto se mide sin ella
			[format ["maniobra %1: %2 sale (%3)", _m get "id", if (isNull (_e get "g")) then {"?"} else {groupId (_e get "g")}, _why]] call VIOC_TAC_fnc_log;
		};
	} forEach (_m get "teams");
	_m set ["teams", (_m get "teams") select {!(_x getOrDefault ["out", false])}];
	if (count (_m get "teams") == 0) exitWith {[_m, "sin escuadras"] call VIOC_TAC_fnc_end};
	//--- el control de atascados de update_ai.fsm (cada 220 s: menos de 25 m -> PlaceSafe a 120 m y recarga) no debe
	//--- teletransportar a las escuadras que esperan en la reunion ni a las del asalto: se borra su referencia (cti_ai_lastpos)
	//--- en cada pasada, como hace airfields con las aeronaves en servicio. Las que van en camino siguen con el control.
	{
		if (((_m get "phase") == "assault") || {_x get "arr"}) then {{_x setVariable ["cti_ai_lastpos", nil]} forEach (units (_x get "g"))};
	} forEach (_m get "teams");
	if ((_m get "phase") == "gather") then {
		//--- una vez, en la primera pasada: se repite el "move" a la reunion por si un hilo viejo de patrulla (que ya habia
		//--- mirado la semilla) alcanzo a mandar a la escuadra a otro lado (no si va en un transporte de ai_transport)
		{
			if (!(_x get "arr") && {!(_x getOrDefault ["mv", false])} && {(time - (_m get "t0")) > 5}) then {
				_x set ["mv", true];
				private _g = _x get "g";
				private _p = _x get "asm";
				if (local _g && {((units _g) findIf {!isNil {_x getVariable "vioc_at_ride"}}) < 0} && {(_g getVariable ["cti_order_pos", []]) isEqualTo _p}) then {_g move _p};
			};
		} forEach (_m get "teams");
		private _all = true;
		private _any = false;
		{
			private _l = leader (_x get "g");
			if (!(_x get "arr") && {alive _l} && {((vehicle _l) distance2D (_x get "asm")) < VIOC_TAC_ARRIVE}) then {
				_x set ["arr", true];
				if ((_m get "tFirst") < 0) then {_m set ["tFirst", time]};
			};
			if (_x get "arr") then {_any = true} else {_all = false};
		} forEach (_m get "teams");
		private _late = (time - (_m get "tp")) > (_m get "gmax");
		if (_all || {_any && {(time - (_m get "tFirst")) > VIOC_TAC_WAIT_REST}} || {_late}) then {
			private _close = ((_m get "teams") findIf {((vehicle (leader (_x get "g"))) distance2D (_m get "obj")) < 1200}) >= 0;
			if (_any || {_close}) then {[_m] call VIOC_TAC_fnc_assault} else {[_m, "no llegaron a la reunion"] call VIOC_TAC_fnc_end};
		};
	} else {
		private _alive = 0;
		{_alive = _alive + ({alive _x} count (units (_x get "g")))} forEach (_m get "teams");
		if ((time - (_m get "tp")) > VIOC_TAC_ASSAULT_TIME) then {[_m, "tiempo de asalto agotado"] call VIOC_TAC_fnc_end} else {
			if (_alive < (VIOC_TAC_WIPE * (_m get "n0"))) then {[_m, "rechazado"] call VIOC_TAC_fnc_end} else {
				private _obj = _m get "obj";
				{
					private _g = _x get "g";
					if (local _g) then {
						_g setCombatMode "RED";
						[_g] call VIOC_TAC_fnc_refollow;
						private _d = (vehicle (leader _g)) distance2D _obj;
						if (_d > 100 && {_d < 550}) then {[_g, _obj, 600] call VIOC_TAC_fnc_suppress};
					};
				} forEach (_m get "teams");
			};
		};
	};
};

//=====================================================================================================================
// Contraataques: perdidas de pueblos y pedidos
//=====================================================================================================================
//--- [pueblo, sideID que lo perdio, sideID nuevo]
VIOC_TAC_fnc_onLost = {
	params ["_t", "_old", "_new"];
	if (VIOC_TAC_CA_MODE <= 0) exitWith {};
	([_t] call VIOC_TAC_fnc_townInfo) params ["_vip", "_imp", "_w"];
	private _tn = [_t] call VIOC_TAC_fnc_tname;
	private _side = (_old) call CTI_CO_FNC_GetSideFromID;
	if (VIOC_TAC_CA_MODE == 1 && {!_imp}) exitWith {[format ["%1 perdio %2: no es importante, sin contraataque (opcion 1)", _side, _tn]] call VIOC_TAC_fnc_log};
	private _p = _w + ([0, 0.2] select (VIOC_TAC_PERSIST >= 2));
	if (!_vip && {(random 1) > _p}) exitWith {[format ["%1 perdio %2: sin contraataque (probabilidad %3)", _side, _tn, _p]] call VIOC_TAC_fnc_log};
	{
		if (((_x get "town") isEqualTo _t) && {(_x get "sid") == _old}) then {_x set ["done", true]};
	} forEach VIOC_TAC_REQ;
	private _win = [1800, 1800, 2700] select (VIOC_TAC_PERSIST max 0 min 2);
	private _due = time + (VIOC_TAC_CA_DELAY select 0) + random ((VIOC_TAC_CA_DELAY select 1) - (VIOC_TAC_CA_DELAY select 0));
	VIOC_TAC_REQ pushBack (createHashMapFromArray [["town", _t], ["sid", _old], ["side", _side], ["t0", time], ["next", _due],
		["end", time + _win], ["tries", 0], ["vip", _vip], ["active", -1], ["done", false], ["forced", false]]);
	[format ["%1 perdio %2 (ahora de %3): contraataque en %4 s (vip %5, probabilidad %6)", _side, _tn, _new, round (_due - time), _vip, _p]] call VIOC_TAC_fnc_log;
};

//--- [pedido] -> true si salio la maniobra
VIOC_TAC_fnc_tryCA = {
	params ["_r"];
	private _side = _r get "side";
	private _t = _r get "town";
	private _vip = _r get "vip";
	//--- ya hay una maniobra del mismo bando sobre ese pueblo (por ejemplo una pinza de un ataque normal): cuenta como el intento
	private _same = VIOC_TAC_MAN findIf {((_x get "side") isEqualTo _side) && {(_x get "town") isEqualTo _t}};
	if (_same >= 0) exitWith {
		private _m = VIOC_TAC_MAN select _same;
		_r set ["active", _m get "id"];
		_r set ["tries", (_r get "tries") + 1];
		_r set ["next", time + ([600, 600, 360] select (VIOC_TAC_PERSIST max 0 min 2))];
		if ((_m get "kind") != "ca") then {_m set ["req", _r]; _m set ["kind", "ca"]};
		if (VIOC_TAC_PERSIST <= 0) then {_r set ["end", time]};
		true
	};
	private _nMan = [_side] call VIOC_TAC_fnc_nMan;
	if (_nMan >= (VIOC_TAC_MAX_MAN + ([0, 1] select _vip))) exitWith {_r set ["next", time + 60]; false};
	private _forced = _r getOrDefault ["forced", false];
	private _n = [VIOC_TAC_CA_TEAMS, VIOC_TAC_CA_TEAMS_VIP] select _vip;
	if (VIOC_TAC_PERSIST >= 2) then {_n = (_n + 1) min 3};
	if (_forced && {(_r getOrDefault ["n", 0]) > 0}) then {_n = ((_r get "n") min 3) max 1}; //--- forzado con cuantas: las mismas en cada reintento
	private _range = if (_forced) then {VIOC_TAC_CA_RANGE_FORCED} else {[VIOC_TAC_CA_RANGE, VIOC_TAC_CA_RANGE_VIP] select _vip};
	private _teams = [_side, _t, _n, _range, _forced] call VIOC_TAC_fnc_pickTeams;
	if (count _teams == 0) exitWith {
		_r set ["next", time + ([120, 60] select _vip)];
		[format ["contraataque de %1 sobre %2: sin escuadras libres, se reintenta", _side, [_t] call VIOC_TAC_fnc_tname]] call VIOC_TAC_fnc_log;
		false
	};
	private _id = ["ca", _side, _t, _teams, _r] call VIOC_TAC_fnc_launch;
	_r set ["active", _id];
	_r set ["tries", (_r get "tries") + 1];
	_r set ["next", time + ([600, 600, 360] select (VIOC_TAC_PERSIST max 0 min 2))];
	if (VIOC_TAC_PERSIST <= 0) then {_r set ["end", time]}; //--- un solo intento
	true
};

VIOC_TAC_fnc_reqTick = {
	{
		private _r = _x;
		if !(_r get "done") then {
			private _t = _r get "town";
			if ((_t getVariable ["cti_town_sideID", -1]) == (_r get "sid")) then {_r set ["done", true]} else {
				private _act = _r get "active";
				if (_act >= 0 && {(VIOC_TAC_MAN findIf {(_x get "id") == _act}) < 0}) then {_r set ["active", -1]; _act = -1};
				if (_act < 0) then {
					if (time > (_r get "end")) then {
						_r set ["done", true];
						[format ["pedido de contraataque de %1 sobre %2 cerrado (%3 intentos)", _r get "side", [_t] call VIOC_TAC_fnc_tname, _r get "tries"]] call VIOC_TAC_fnc_log;
					} else {
						if (time >= (_r get "next")) then {[_r] call VIOC_TAC_fnc_tryCA};
					};
				};
			};
		};
	} forEach VIOC_TAC_REQ;
	VIOC_TAC_REQ = VIOC_TAC_REQ select {!(_x get "done")};
};

VIOC_TAC_fnc_watchTowns = {
	{
		private _t = _x;
		private _sid = _t getVariable ["cti_town_sideID", -1];
		private _old = _t getVariable ["vioc_tac_sid", -99];
		if (_old != _sid) then {
			_t setVariable ["vioc_tac_sid", _sid];
			if (_old in [CTI_WEST_ID, CTI_EAST_ID]) then {[_t, _old, _sid] call VIOC_TAC_fnc_onLost};
		};
	} forEach CTI_Towns;
};

//=====================================================================================================================
// Pinza en los ataques normales (2-3 escuadras de un bando hacia el mismo pueblo)
//=====================================================================================================================
VIOC_TAC_fnc_pinScan = {
	{
		private _side = _x;
		private _sid = (_side) call CTI_CO_FNC_GetSideID;
		if (([_side] call VIOC_TAC_fnc_nMan) < VIOC_TAC_MAX_MAN) then {
			private _cmd = [_side] call VIOC_TAC_fnc_cmd;
			private _human = !isNull _cmd && {isPlayer (leader _cmd)};
			private _orders = if (_human) then {[CTI_ORDER_TAKETOWN_AUTO, CTI_ORDER_TAKEHOLDTOWN_AUTO]} else {VIOC_TAC_ORDERS_TAKE};
			private _towns = [];
			private _lists = [];
			{
				private _g = _x;
				if ([_g, _side, _cmd, _human] call VIOC_TAC_fnc_teamOk) then {
					private _p = _g getVariable ["cti_order_pos", objNull];
					if (((_g getVariable ["cti_order", -1]) in _orders) && {_p isEqualType objNull} && {!isNull _p} && {_p in CTI_Towns}
						&& {(_p getVariable ["cti_town_sideID", -1]) != _sid}) then {
						private _d = (vehicle (leader _g)) distance2D _p;
						if (_d > (VIOC_TAC_PIN_R select 0) && {_d < (VIOC_TAC_PIN_R select 1)} && {!([leader _g, 300] call VIOC_TAC_fnc_inCombat)}) then {
							private _i = _towns find _p;
							if (_i < 0) then {_towns pushBack _p; _lists pushBack [[_d, _g]]} else {(_lists select _i) pushBack [_d, _g]};
						};
					};
				};
			} forEach ((_side) call CTI_CO_FNC_GetSideGroups);
			private _done = false;
			{
				private _t = _x;
				private _l = _lists select _forEachIndex;
				if (!_done && {count _l >= 2} && {(_t getVariable [format ["vioc_tac_pin%1", _sid], -1]) < time}
					&& {(VIOC_TAC_MAN findIf {((_x get "town") isEqualTo _t) && {(_x get "side") isEqualTo _side}}) < 0}) then {
					private _room = [_side, _cmd] call VIOC_TAC_fnc_sideRoom;
					if (_room >= 2) then {
						private _keys = [];
						{_keys pushBack [_x select 0, _forEachIndex]} forEach _l;
						_keys sort true;
						private _teams = (_keys select [0, 3 min _room]) apply {(_l select (_x select 1)) select 1};
						_t setVariable [format ["vioc_tac_pin%1", _sid], time + VIOC_TAC_PIN_COOLDOWN];
						["pin", _side, _t, _teams, createHashMap] call VIOC_TAC_fnc_launch;
						_done = true;
					};
				};
			} forEach _towns;
		};
	} forEach [west, east];
};

//=====================================================================================================================
// Pinza defensiva de las guarniciones
//=====================================================================================================================
//--- -> [pueblos, listas de grupos]: guarniciones marcadas por town_patrol.fsm, locales, con gente viva y SOLO del bando que
//--- hoy tiene el pueblo (los sobrevivientes del duenio anterior siguen marcados: town_resistance.fsm y las listas de
//--- huerfanos de perf_cleanup los mantienen un tiempo)
VIOC_TAC_fnc_garrisons = {
	private _towns = [];
	private _lists = [];
	{
		private _g = _x;
		private _t = _g getVariable ["vioc_tac_town", objNull];
		if (!isNull _t && {local _g} && {({alive _x} count (units _g)) > 0}
			&& {(side _g) isEqualTo ((_t getVariable ["cti_town_sideID", -1]) call CTI_CO_FNC_GetSideFromID)}) then {
			private _i = _towns find _t;
			if (_i < 0) then {_towns pushBack _t; _lists pushBack [_g]} else {(_lists select _i) pushBack _g};
		};
	} forEach allGroups;
	[_towns, _lists]
};

//--- [grupo, posicion]: converger sobre el atacante
VIOC_TAC_fnc_qrfWp = {
	params ["_g", "_A"];
	[_g] call VIOC_TAC_fnc_clearWp;
	_g setCombatMode "RED";
	_g setBehaviour "COMBAT";
	_g setSpeedMode "NORMAL";
	private _w = _g addWaypoint [_A, 20];
	_w setWaypointType "SAD";
	_w setWaypointBehaviour "COMBAT";
	_w setWaypointCombatMode "RED";
	_w setWaypointCompletionRadius 40;
	private _w2 = _g addWaypoint [_A, 50];
	_w2 setWaypointType "SAD";
	_w2 setWaypointCompletionRadius 40;
	_g setCurrentWaypoint _w;
};

//--- [pueblo, grupos de la guarnicion, forzado] -> texto (que paso)
VIOC_TAC_fnc_qrfTry = {
	params ["_t", "_gs", "_forced"];
	if (!_forced && {(_t getVariable ["vioc_tac_qrfT", -1]) > time}) exitWith {"en espera"};
	if ((VIOC_TAC_QRF findIf {(_x get "town") isEqualTo _t}) >= 0) exitWith {"ya hay una pinza defensiva en marcha"};
	private _gside = (_t getVariable ["cti_town_sideID", -1]) call CTI_CO_FNC_GetSideFromID; //--- el duenio de hoy
	_gs = _gs select {(side _x) isEqualTo _gside};
	if (count _gs == 0) exitWith {"sin guarnicion del duenio actual"};
	private _tp = [_t] call VIOC_TAC_fnc_p0;
	private _R = _t getVariable ["cti_town_range", 550];
	//--- atacantes que conocen los jefes de la guarnicion
	private _cands = [];
	{
		private _l = leader _x;
		if (!isNull _l && {alive _l}) then {
			{
				if (alive _x && {(_l knowsAbout _x) > 1.5} && {!(_x isKindOf "Air")} && {(_x distance2D _tp) >= VIOC_TAC_QRF_MINR}) then {_cands pushBackUnique _x};
			} forEach (_l targets [true, _R + VIOC_TAC_QRF_EXTRA, [], 90, _tp]);
		};
	} forEach (_gs select [0, 4]);
	if (count _cands == 0) exitWith {"sin atacantes conocidos"};
	private _best = objNull;
	private _bd = 1e9;
	{
		private _d = _x distance2D _tp;
		if (_d < _bd) then {_bd = _d; _best = _x};
	} forEach _cands;
	private _ag = if (_best isKindOf "Man") then {group _best} else {group (effectiveCommander _best)};
	if (isNull _ag) exitWith {"sin grupo atacante"};
	private _A = [(_cands select {(_x distance2D _best) < 250}) apply {getPosATL _x}] call VIOC_TAC_fnc_avg;
	if ((_A distance2D _tp) < VIOC_TAC_QRF_MINR) exitWith {"atacantes ya dentro del pueblo"};
	//--- grupos de la pinza: en la capital como mucho la mitad, en los demas queda al menos uno; 2 como mucho
	private _total = count _gs;
	private _maxq = (if (_t getVariable ["vioc_capital", false]) then {floor (_total / 2)} else {_total - 1}) min 2;
	if (_maxq < 1) exitWith {"guarnicion demasiado chica"};
	private _keys = [];
	{
		private _g = _x;
		private _l = leader _g;
		private _v = objectParent _l;
		if (!(_g getVariable ["vioc_tac_busy", false]) && {alive _l} && {!isPlayer _l} && {((units _g) findIf {isPlayer _x}) < 0}
			&& {({alive _x} count (units _g)) >= 3} && {isNull _v || {(_v isKindOf "LandVehicle") && {!(_v isKindOf "StaticWeapon")}}}
			&& {((vehicle _l) distance2D _A) > 120}) then {_keys pushBack [(vehicle _l) distance2D _A, _forEachIndex]};
	} forEach _gs;
	_keys sort true;
	private _sel = (_keys select [0, _maxq]) apply {_gs select (_x select 1)};
	if (count _sel == 0) exitWith {"sin grupos libres"};
	//--- puntos de flanqueo a los dos lados del atacante (perpendiculares al eje atacante -> pueblo)
	private _dir = _A getDir _tp;
	private _base = _A getPos [60, _dir];
	private _radii = [VIOC_TAC_QRF_OFFSET, VIOC_TAC_QRF_OFFSET - 50, VIOC_TAC_QRF_OFFSET + 50];
	private _fl = [[_base, _radii, _dir - 90] call VIOC_TAC_fnc_landPoint, [_base, _radii, _dir + 90] call VIOC_TAC_fnc_landPoint] select {count _x > 1};
	if (count _fl == 0) exitWith {"sin puntos de flanqueo en tierra"};
	if (count _fl == 1) then {_sel = [_sel select 0]};
	private _ls = _sel apply {getPosATL (vehicle (leader _x))};
	private _asg = [];
	if (count _sel == 1) then {
		private _p = _fl select 0;
		if (count _fl > 1 && {((_ls select 0) distance2D (_fl select 1)) < ((_ls select 0) distance2D _p)}) then {_p = _fl select 1};
		_asg = [[_sel select 0, _p]];
	} else {
		private _pm = [_ls, _fl] call VIOC_TAC_fnc_bestPerm;
		{_asg pushBack [_x, _fl select (_pm select _forEachIndex)]} forEach _sel;
	};
	private _q = createHashMapFromArray [["id", VIOC_TAC_NEXTID], ["town", _t], ["side", _gside], ["ag", _ag], ["A", _A],
		["phase", "flank"], ["t0", time], ["tp", time], ["groups", []], ["done", false]];
	VIOC_TAC_NEXTID = VIOC_TAC_NEXTID + 1;
	private _dirs = [];
	{
		_x params ["_g", "_p"];
		private _e = createHashMapFromArray [["g", _g], ["F", _p], ["arr", false], ["wpA", [0, 0, 0]],
			["cm", combatMode _g], ["beh", behaviour (leader _g)], ["spd", speedMode _g]];
		_g setVariable ["vioc_tac_busy", true];
		[_g] call VIOC_TAC_fnc_clearWp;
		_g setCombatMode "YELLOW";
		_g setBehaviour "AWARE";
		_g setSpeedMode "FULL";
		private _w = _g addWaypoint [_p, 0];
		_w setWaypointType "MOVE";
		_w setWaypointCompletionRadius 40;
		_g setCurrentWaypoint _w;
		(_q get "groups") pushBack _e;
		_dirs pushBackUnique ([_A getDir _p] call VIOC_TAC_fnc_dirName);
	} forEach _asg;
	VIOC_TAC_QRF pushBack _q;
	_t setVariable ["vioc_tac_qrfT", time + VIOC_TAC_QRF_FLANK_TIME + VIOC_TAC_QRF_TIME + VIOC_TAC_QRF_COOLDOWN];
	[5] call VIOC_TAC_fnc_stat;
	private _tn = [_t] call VIOC_TAC_fnc_tname;
	if (_gside in [west, east]) then {
		[_gside, format ["[Defensa] La guarnicion de %1 sale a flanquear a los atacantes (%2 grupo%3, por %4).", _tn, count _asg,
			if (count _asg > 1) then {"s"} else {""}, _dirs joinString " y "]] call VIOC_TAC_fnc_say;
	};
	private _res = format ["pinza defensiva %1 en %2 (%3): %4 de %5 grupos contra %6 (%7, a %8 m del centro)", _q get "id", _tn, _gside,
		count _asg, _total, groupId _ag, side _ag, round (_A distance2D _tp)];
	[_res] call VIOC_TAC_fnc_log;
	_res
};

//--- [pueblo forzado o objNull] -> texto (solo para el forzado)
VIOC_TAC_fnc_qrfScan = {
	params [["_force", objNull]];
	if (count VIOC_TAC_QRF >= VIOC_TAC_QRF_MAX && {isNull _force}) exitWith {""};
	([] call VIOC_TAC_fnc_garrisons) params ["_towns", "_lists"];
	private _vip = [];
	private _rest = [];
	{
		if (isNull _force || {_x isEqualTo _force}) then {
			if ((_x getVariable ["vioc_capital", false]) || {_x in VIOC_TAC_AF}) then {_vip pushBack _forEachIndex} else {_rest pushBack _forEachIndex};
		};
	} forEach _towns;
	_rest = _rest call CTI_CO_FNC_ArrayShuffle;
	if (count _rest > VIOC_TAC_QRF_TOWNS) then {_rest resize VIOC_TAC_QRF_TOWNS};
	private _msg = "";
	{
		if ((count VIOC_TAC_QRF < VIOC_TAC_QRF_MAX) || {!isNull _force}) then {
			_msg = [_towns select _x, _lists select _x, !isNull _force] call VIOC_TAC_fnc_qrfTry;
		};
	} forEach (_vip + _rest);
	if (!isNull _force && {_msg == ""}) then {_msg = "ese pueblo no tiene guarnicion activa (sin enemigos cerca la mision no la crea)"};
	_msg
};

//--- [grupo de la pinza (hashmap)]
VIOC_TAC_fnc_qrfRelease = {
	params ["_e"];
	private _g = _e get "g";
	if (isNull _g) exitWith {};
	if (local _g) then {
		[_g] call VIOC_TAC_fnc_clearWp;
		_g setCombatMode (_e get "cm");
		_g setBehaviour (_e get "beh");
		_g setSpeedMode (_e get "spd");
		private _l = leader _g;
		{
			_x setVariable ["vioc_tac_supT", nil];
			if (alive _x && {!isPlayer _x} && {!(_x isEqualTo _l)}) then {_x doFollow _l};
		} forEach (units _g);
	};
	_g setVariable ["vioc_tac_busy", nil]; //--- town_patrol.fsm vuelve a patrullar o a defender el pueblo
};

VIOC_TAC_fnc_qrfEnd = {
	params ["_q", "_why"];
	if (_q get "done") exitWith {};
	_q set ["done", true];
	{[_x] call VIOC_TAC_fnc_qrfRelease} forEach (_q get "groups");
	(_q get "town") setVariable ["vioc_tac_qrfT", time + VIOC_TAC_QRF_COOLDOWN];
	if (_why == "atacantes eliminados") then {[6] call VIOC_TAC_fnc_stat};
	[format ["pinza defensiva %1 en %2 terminada: %3", _q get "id", [_q get "town"] call VIOC_TAC_fnc_tname, _why]] call VIOC_TAC_fnc_log;
	VIOC_TAC_QRF = VIOC_TAC_QRF select {!(_x get "done")};
};

VIOC_TAC_fnc_qrfConverge = {
	params ["_q"];
	_q set ["phase", "converge"];
	_q set ["tp", time];
	private _A = _q get "A";
	{
		private _g = _x get "g";
		if (local _g) then {
			[_g, _A] call VIOC_TAC_fnc_qrfWp;
			_x set ["wpA", _A];
			[_g, _A, 600] call VIOC_TAC_fnc_suppress;
		};
	} forEach (_q get "groups");
	[format ["pinza defensiva %1: convergen sobre %2", _q get "id", _A]] call VIOC_TAC_fnc_log;
};

VIOC_TAC_fnc_qrfTick = {
	params ["_q"];
	if (_q get "done") exitWith {};
	private _t = _q get "town";
	private _tp = [_t] call VIOC_TAC_fnc_p0;
	{
		private _g = _x get "g";
		if (isNull _g || {({alive _x} count (units _g)) == 0} || {isPlayer (leader _g)} || {((units _g) findIf {isPlayer _x}) >= 0}) then {
			[_x] call VIOC_TAC_fnc_qrfRelease;
			_x set ["out", true];
		};
	} forEach (_q get "groups");
	_q set ["groups", (_q get "groups") select {!(_x getOrDefault ["out", false])}];
	private _end = "";
	if (count (_q get "groups") == 0) then {_end = "sin grupos"};
	if (_end == "" && {(_t getVariable ["cti_town_sideID", -1]) != ((_q get "side") call CTI_CO_FNC_GetSideID)}) then {_end = "pueblo perdido"};
	private _ag = _q get "ag";
	private _alive = if (isNull _ag) then {[]} else {(units _ag) select {alive _x}};
	if (_end == "" && {count _alive == 0}) then {_end = "atacantes eliminados"};
	if (_end == "") then {
		private _gl = (_q get "groups") apply {leader (_x get "g")};
		private _known = _alive select {private _u = _x; (_gl findIf {alive _x && {(_x knowsAbout _u) > 1}}) >= 0};
		if (count _known > 0) then {_q set ["A", [_known apply {getPosATL (vehicle _x)}] call VIOC_TAC_fnc_avg]};
		if (((_q get "A") distance2D _tp) > ((_t getVariable ["cti_town_range", 550]) + 700)) then {_end = "atacantes se retiraron"};
	};
	if (_end == "") then {
		if ((_q get "phase") == "flank") then {
			private _all = true;
			{
				private _l = leader (_x get "g");
				if (!(_x get "arr") && {((vehicle _l) distance2D (_x get "F")) < 60}) then {_x set ["arr", true]};
				if !(_x get "arr") then {_all = false};
			} forEach (_q get "groups");
			if (_all || {(time - (_q get "tp")) > VIOC_TAC_QRF_FLANK_TIME}) then {[_q] call VIOC_TAC_fnc_qrfConverge};
		} else {
			if ((time - (_q get "tp")) > VIOC_TAC_QRF_TIME) then {_end = "tiempo"} else {
				private _A = _q get "A";
				{
					private _g = _x get "g";
					if (local _g) then {
						_g setCombatMode "RED";
						[_g] call VIOC_TAC_fnc_refollow;
						if (((_x get "wpA") distance2D _A) > 100) then {[_g, _A] call VIOC_TAC_fnc_qrfWp; _x set ["wpA", _A]};
						[_g, _A, 600] call VIOC_TAC_fnc_suppress;
					};
				} forEach (_q get "groups");
			};
		};
	};
	if (_end != "") then {[_q, _end] call VIOC_TAC_fnc_qrfEnd};
};

//=====================================================================================================================
// Bucle
//=====================================================================================================================
VIOC_TAC_fnc_tick = {
	call VIOC_TAC_fnc_watchTowns;
	{[_x] call VIOC_TAC_fnc_manTick} forEach (VIOC_TAC_MAN + []); //--- copia SUPERFICIAL (los mismos hashmaps): el + unario copiaria todo y se perderia el estado
	if (VIOC_TAC_CA_MODE > 0) then {call VIOC_TAC_fnc_reqTick};
	if (VIOC_TAC_PINCER > 0) then {call VIOC_TAC_fnc_pinScan};
	{[_x] call VIOC_TAC_fnc_qrfTick} forEach (VIOC_TAC_QRF + []);
	if (VIOC_TAC_PINCER > 1) then {[objNull] call VIOC_TAC_fnc_qrfScan};
};

VIOC_TAC_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 60; //--- despues de towns_capital (40 s) y de airfields (30 s)
	VIOC_TAC_ON = missionNamespace getVariable ["VIOC_AI_TACTICS", 1];
	VIOC_TAC_CA_MODE = missionNamespace getVariable ["VIOC_AI_COUNTERATTACK", 2];
	VIOC_TAC_PERSIST = missionNamespace getVariable ["VIOC_AI_CA_PERSIST", 1];
	VIOC_TAC_PINCER = missionNamespace getVariable ["VIOC_AI_PINCER", 2];
	VIOC_TAC_INTEL = missionNamespace getVariable ["VIOC_AI_CA_INTEL", 0];
	{
		if !((missionNamespace getVariable [_x select 0, 0]) isEqualType 0) then {missionNamespace setVariable [_x select 0, _x select 1]};
	} forEach [["VIOC_TAC_ON", 1], ["VIOC_TAC_CA_MODE", 2], ["VIOC_TAC_PERSIST", 1], ["VIOC_TAC_PINCER", 2], ["VIOC_TAC_INTEL", 0]];
	if (VIOC_TAC_ON <= 0) exitWith {["apagado (VIOC_AI_TACTICS = 0)"] call VIOC_TAC_fnc_log};
	VIOC_TAC_ORDERS_TAKE = [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKETOWN_AUTO, CTI_ORDER_TAKEHOLDTOWN, CTI_ORDER_TAKEHOLDTOWN_AUTO];
	VIOC_TAC_ORDERS_AUTO = [CTI_ORDER_TAKETOWNS, CTI_ORDER_TAKETOWN_AUTO, CTI_ORDER_TAKEHOLDTOWNS, CTI_ORDER_TAKEHOLDTOWN_AUTO, CTI_ORDER_HOLDTOWNSBASES];
	VIOC_TAC_ORDERS_AI = VIOC_TAC_ORDERS_AUTO + [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKEHOLDTOWN, CTI_ORDER_HOLDTOWNSBASE];
	VIOC_TAC_AF = call VIOC_TAC_fnc_airfieldTowns;
	{_x setVariable ["vioc_tac_sid", _x getVariable ["cti_town_sideID", -1]]} forEach CTI_Towns;
	VIOC_TAC_READY = true;
	[format ["activo: contraataque %1, insistencia %2, pinza %3, aviso %4; %5 pueblos, aerodromos %6, capital %7", VIOC_TAC_CA_MODE, VIOC_TAC_PERSIST,
		VIOC_TAC_PINCER, VIOC_TAC_INTEL, count CTI_Towns, VIOC_TAC_AF apply {[_x] call VIOC_TAC_fnc_tname},
		(CTI_Towns select {_x getVariable ["vioc_capital", false]}) apply {[_x] call VIOC_TAC_fnc_tname}]] call VIOC_TAC_fnc_log;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		sleep VIOC_TAC_PERIOD;
		call VIOC_TAC_fnc_tick;
	};
	call VIOC_TAC_fnc_stopAll;
};

//=====================================================================================================================
// Consola
//=====================================================================================================================
VIOC_TAC_fnc_stopAll = {
	{[_x, "detenido"] call VIOC_TAC_fnc_end} forEach (VIOC_TAC_MAN + []);
	{[_x, "detenido"] call VIOC_TAC_fnc_qrfEnd} forEach (VIOC_TAC_QRF + []);
	{_x set ["done", true]} forEach VIOC_TAC_REQ;
	VIOC_TAC_REQ = [];
	"VIOC ai_tactics: todo detenido; las escuadras recuperan sus ordenes"
};

//--- [pueblo (por defecto el mas cercano a ti), bando (por defecto el contrario al duenio), escuadras (0 = las normales)] -> texto
VIOC_TAC_fnc_forceCA = {
	params [["_town", objNull], ["_side", sideUnknown], ["_n", 0]];
	if !(VIOC_TAC_READY) exitWith {"VIOC ai_tactics: todavia arrancando (1 min despues de los pueblos) o apagado en el lobby"};
	if (isNull _town) then {_town = call VIOC_TAC_fnc_nearTown};
	if (isNull _town) exitWith {"no hay pueblos"};
	private _owner = _town getVariable ["cti_town_sideID", -1];
	if !(_side in [west, east]) then {_side = [west, east] select (_owner == CTI_WEST_ID)};
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	if (_owner == _sid) exitWith {format ["%1 ya es de %2", [_town] call VIOC_TAC_fnc_tname, _side]};
	{
		if (((_x get "town") isEqualTo _town) && {(_x get "sid") == _sid}) then {_x set ["done", true]};
	} forEach VIOC_TAC_REQ;
	private _r = createHashMapFromArray [["town", _town], ["sid", _sid], ["side", _side], ["t0", time], ["next", time],
		["end", time + 1800], ["tries", 0], ["vip", true], ["active", -1], ["done", false], ["forced", true], ["n", [0, _n] select (_n isEqualType 0)]];
	VIOC_TAC_REQ pushBack _r;
	if ([_r] call VIOC_TAC_fnc_tryCA) then {
		private _m = VIOC_TAC_MAN select (VIOC_TAC_MAN findIf {(_x get "id") == (_r get "active")});
		format ["Contraataque forzado de %1 sobre %2 con %3: %4", _side, [_town] call VIOC_TAC_fnc_tname, ((_m get "teams") apply {groupId (_x get "g")}) joinString ", ",
			"mira el mapa con call VIOC_TAC_fnc_markers"]
	} else {
		format ["%1 no tiene escuadras libres para %2 (a menos de %3 m, por tierra, sin combate cerca); se reintenta cada minuto durante 30 min", _side, [_town] call VIOC_TAC_fnc_tname, VIOC_TAC_CA_RANGE_FORCED]
	};
};

//--- [pueblo (por defecto el mas cercano a ti)] -> texto
VIOC_TAC_fnc_forceQRF = {
	params [["_town", objNull]];
	if !(VIOC_TAC_READY) exitWith {"VIOC ai_tactics: todavia arrancando o apagado en el lobby"};
	if (isNull _town) then {_town = call VIOC_TAC_fnc_nearTown};
	if (isNull _town) exitWith {"no hay pueblos"};
	_town setVariable ["vioc_tac_qrfT", -1];
	format ["%1: %2", [_town] call VIOC_TAC_fnc_tname, [_town] call VIOC_TAC_fnc_qrfScan]
};

VIOC_TAC_fnc_info = {
	private _lines = [format ["VIOC ai_tactics: activo %1 (listo %2), contraataque %3, insistencia %4, pinza %5, aviso %6 | INFO %7 | aerodromos %8",
		VIOC_TAC_ON, VIOC_TAC_READY, VIOC_TAC_CA_MODE, VIOC_TAC_PERSIST, VIOC_TAC_PINCER, VIOC_TAC_INTEL, VIOC_TAC_INFO, VIOC_TAC_AF apply {[_x] call VIOC_TAC_fnc_tname}]];
	{
		private _m = _x;
		_lines pushBack format ["#%1 %2 de %3 sobre %4: %5 desde hace %6 s (plazo de reunion %7 s), objetivo a %8 m del centro", _m get "id",
			["pinza", "contraataque"] select ((_m get "kind") == "ca"), _m get "side", [_m get "town"] call VIOC_TAC_fnc_tname, _m get "phase",
			round (time - (_m get "tp")), round (_m get "gmax"), round ((_m get "obj") distance2D (_m get "town"))];
		{
			private _g = _x get "g";
			if (!isNull _g) then {
				private _l = vehicle (leader _g);
				_lines pushBack format ["   %1: %2 vivos, a %3 m de la reunion (%4), a %5 m del objetivo, orden %6", groupId _g, {alive _x} count (units _g),
					round (_l distance2D (_x get "asm")), ["en camino", "llego"] select (_x get "arr"), round (_l distance2D (_m get "obj")), _g getVariable ["cti_order", -1]];
			};
		} forEach (_m get "teams");
	} forEach VIOC_TAC_MAN;
	{
		_lines pushBack format ["Pedido: %1 contraataca %2 (vip %3, forzado %7): %4 intentos, proximo en %5 s, ventana hasta %6 s", _x get "side", [_x get "town"] call VIOC_TAC_fnc_tname,
			_x get "vip", _x get "tries", round (((_x get "next") - time) max 0), round (((_x get "end") - time) max 0), _x getOrDefault ["forced", false]];
	} forEach VIOC_TAC_REQ;
	{
		private _q = _x;
		private _ag = _q get "ag";
		_lines pushBack format ["Pinza defensiva #%1 en %2 (%3): %4 desde hace %5 s, %6 grupos, atacante %7 (%8 vivos) a %9 m del centro", _q get "id",
			[_q get "town"] call VIOC_TAC_fnc_tname, _q get "side", _q get "phase", round (time - (_q get "tp")), count (_q get "groups"),
			if (isNull _ag) then {"-"} else {groupId _ag}, if (isNull _ag) then {0} else {{alive _x} count (units _ag)}, round ((_q get "A") distance2D (_q get "town"))];
	} forEach VIOC_TAC_QRF;
	private _txt = _lines joinString (toString [10]);
	copyToClipboard _txt;
	_txt
};

//--- Marcadores LOCALES (solo en la maquina que lo ejecuta) de lo que esta en marcha, cada 5 s; otra vez para apagar.
VIOC_TAC_fnc_markers = {
	if (!hasInterface) exitWith {"sin interfaz"};
	if (missionNamespace getVariable ["VIOC_TAC_MK_ON", false]) exitWith {VIOC_TAC_MK_ON = false; "VIOC ai_tactics: marcadores apagados"};
	VIOC_TAC_MK_ON = true;
	[] spawn {
		private _mine = [];
		private _k = 0;
		private _fnc_mk = {
			params ["_pos", "_type", "_color", "_text"];
			_k = _k + 1;
			private _mk = createMarkerLocal [format ["vioc_tac_mk_%1", _k], [_pos select 0, _pos select 1]];
			_mk setMarkerTypeLocal _type;
			_mk setMarkerColorLocal _color;
			_mk setMarkerTextLocal _text;
			_mine pushBack _mk;
		};
		while {missionNamespace getVariable ["VIOC_TAC_MK_ON", false]} do {
			{deleteMarkerLocal _x} forEach _mine;
			_mine = [];
			{
				private _m = _x;
				private _col = if ((_m get "side") isEqualTo west) then {"ColorBlue"} else {"ColorRed"};
				private _tag = format ["%1#%2", ["PINZA", "CA"] select ((_m get "kind") == "ca"), _m get "id"];
				[_m get "obj", "mil_objective", _col, format ["%1 objetivo (%2)", _tag, _m get "phase"]] call _fnc_mk;
				{
					private _g = _x get "g";
					[_x get "asm", "mil_flag", _col, format ["%1 reunion", _tag]] call _fnc_mk;
					if (!isNull _g) then {[getPosATL (vehicle (leader _g)), "mil_dot", _col, format ["%1 %2", _tag, groupId _g]] call _fnc_mk};
				} forEach (_m get "teams");
			} forEach VIOC_TAC_MAN;
			{
				private _q = _x;
				private _tag = format ["DEF#%1", _q get "id"];
				[_q get "A", "mil_warning", "ColorOrange", format ["%1 atacante", _tag]] call _fnc_mk;
				{
					private _g = _x get "g";
					[_x get "F", "mil_triangle", "ColorGreen", format ["%1 flanco", _tag]] call _fnc_mk;
					if (!isNull _g) then {[getPosATL (vehicle (leader _g)), "mil_dot", "ColorGreen", format ["%1 %2 (%3)", _tag, groupId _g, _q get "phase"]] call _fnc_mk};
				} forEach (_q get "groups");
			} forEach VIOC_TAC_QRF;
			{
				[getPosATL (_x get "town"), "mil_dot", "ColorYellow", format ["CA pendiente: %1 en %2 s", _x get "side", round (((_x get "next") - time) max 0)]] call _fnc_mk;
			} forEach VIOC_TAC_REQ;
			sleep 5;
		};
		{deleteMarkerLocal _x} forEach _mine;
	};
	"VIOC ai_tactics: marcadores encendidos (azul/rojo: maniobras de Oeste/Este; verde: pinza defensiva; amarillo: contraataque pendiente)"
};

[] spawn VIOC_TAC_fnc_loop;

